#!/usr/bin/env bash
#
# @name_k8s@ -- generated by pipeline/generate.py. Do not edit; regenerate.
#
# Runs @benchmark@ end to end on EIDF. Start it and walk away:
#
#     bash @name_k8s@.sh
#
# WHY THIS IS A SCRIPT AND NOT AN UNATTENDED JOB
# ----------------------------------------------
# Every other TEASBench run is one self-contained k8s Job. @benchmark@ on EIDF
# cannot be, because EIDF does not grant pods RBAC: the driver has to create a
# sandbox Job per task through the k8s API, and the only credentials that can do
# that here are yours, which live on this login node rather than in a pod.
#
# The GPUs are still used through Kubernetes, exactly as always. This script
# creates three kinds of Job on your behalf:
#
#     engine   Job, GPU     -- serves the model                 (this script)
#     sandbox  Job, no GPU  -- swe-rex, one per task            (the driver)
#     eval     Job, no GPU  -- official grading, one per task    (the driver)
#
# and reaches each of them over `kubectl port-forward`. Only the driver process
# itself runs here.
#
# The engine Job is deleted on exit -- success, failure or Ctrl-C -- so an
# aborted run cannot leave GPUs allocated.
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENGINE_MANIFEST="$HERE/@engine_manifest@"
NAMESPACE="${TEASBENCH_K8S_NAMESPACE:-eidf230ns}"
RUN_NAME="@name_k8s@"
LOCAL_PORT="${LOCAL_PORT:-0}"          # 0 = pick a free port, avoiding collisions
ENGINE_TIMEOUT="${ENGINE_TIMEOUT:-3600}"
OUTPUT_ROOT="${OUTPUT_ROOT:-$HOME/teasbench-runs}"
RESUME=""
PUSH=1

while [[ $# -gt 0 ]]; do
    case "$1" in
        --namespace)   NAMESPACE="$2"; shift 2 ;;
        --output-root) OUTPUT_ROOT="$2"; shift 2 ;;
        --resume)      RESUME="--resume"; shift ;;
        --no-push)     PUSH=0; shift ;;
        -h|--help)     sed -n '2,30p' "${BASH_SOURCE[0]}"; exit 0 ;;
        *) echo "unknown arg: $1" >&2; exit 2 ;;
    esac
done

TIMESTAMP="$(date +%Y%m%d-%H%M)"
RUN_DIR="$OUTPUT_ROOT/$RUN_NAME/$TIMESTAMP"
mkdir -p "$RUN_DIR"

# One run per output dir: a second concurrent driver would corrupt results.jsonl
# and the per-task stream stats.
exec 9>"$RUN_DIR/.run.lock"
flock -n 9 || { echo "ERROR: another driver is already active on $RUN_DIR" >&2; exit 1; }

echo "=============================================================="
echo "$RUN_NAME"
echo "  namespace : $NAMESPACE"
echo "  benchmark : @benchmark@  (@num_tasks@ tasks, concurrency @concurrency@)"
echo "  run dir   : $RUN_DIR"
echo "=============================================================="

ENGINE_JOB=""
PF_PID=""

cleanup() {
    local rc=$?
    echo
    echo "[cleanup] tearing down"
    [ -n "$PF_PID" ] && kill "$PF_PID" 2>/dev/null && echo "  port-forward stopped"
    if [ -n "$ENGINE_JOB" ]; then
        # The engine holds GPUs; deleting it is the single most important thing
        # this script does on the way out.
        kubectl -n "$NAMESPACE" delete job "$ENGINE_JOB" --wait=false --ignore-not-found=true \
            > /dev/null 2>&1 && echo "  engine job $ENGINE_JOB deleted"
    fi
    # Sandboxes are deleted by the provider per task; leftovers mean a crash.
    local left
    left=$(kubectl -n "$NAMESPACE" get jobs -l app=teasbench-sandbox --no-headers 2>/dev/null | wc -l | tr -d ' ')
    if [ "${left:-0}" -gt 0 ]; then
        echo "  WARNING: $left sandbox job(s) left behind; deleting"
        kubectl -n "$NAMESPACE" delete jobs -l app=teasbench-sandbox --wait=false > /dev/null 2>&1
    fi
    exit $rc
}
trap cleanup EXIT INT TERM

echo
echo "[1] Prerequisites"
fail=0
chk() { if eval "$2" > /dev/null 2>&1; then echo "  ok    $1"; else echo "  FAIL  $1"; [ -n "${3:-}" ] && echo "        $3"; fail=1; fi; }

chk "kubectl reaches $NAMESPACE"      "kubectl -n '$NAMESPACE' get pods"
chk "can create jobs"                 "[ \"\$(kubectl -n '$NAMESPACE' auth can-i create jobs)\" = yes ]"
chk "can create pods/portforward"     "[ \"\$(kubectl -n '$NAMESPACE' auth can-i create pods/portforward)\" = yes ]" \
    "Without this the driver cannot reach the engine or any sandbox."
chk "agent_cap importable"            "python3 -c 'import agent_cap'"
chk "swe-rex importable"              "python3 -c 'import swerex'"
chk "swebench importable"             "python3 -c 'import swebench'"
chk "provider importable"             "PYTHONPATH='@teasbench_root@' python3 -c 'from teasbench.sandbox.k8s import PortForwardK8sProvider'"
chk "engine manifest present"         "[ -f '$ENGINE_MANIFEST' ]" "Regenerate with pipeline/generate.py."
AGENTCAP_DIR="${AGENTCAP_DIR:-$(cd "@teasbench_root@/../AgentCAP-teasbench" 2>/dev/null && pwd || echo "$HOME/AgentCAP")}"
chk "AgentCAP checkout ($AGENTCAP_DIR)" "[ -f '$AGENTCAP_DIR/benchmarks/swe_bench_lite_curated_100.json' ]" \
    "Set AGENTCAP_DIR to your AgentCAP checkout."

# A missing streaming patch yields a complete run with empty metrics -- an
# expensive silent failure, so it is a hard precondition.
SWEAGENT_DIR="${SWEAGENT_DIR:-$HOME/swe_agent}"
chk "SWE-agent streaming-patched"     "grep -q AGENTCAP_STREAMING_PATCH_APPLIED '$SWEAGENT_DIR/sweagent/agent/models.py'" \
    "python \$AGENTCAP_DIR/scripts/patch_sweagent_streaming.py $SWEAGENT_DIR"

[ $fail -eq 0 ] || { echo; echo "Prerequisites failed -- nothing started."; exit 1; }

echo
echo "[2] Starting the engine (GPU Job)"
ENGINE_JOB=$(kubectl -n "$NAMESPACE" create -f "$ENGINE_MANIFEST" -o jsonpath='{.metadata.name}')
[ -n "$ENGINE_JOB" ] || { echo "ERROR: engine Job not created" >&2; exit 1; }
echo "  job: $ENGINE_JOB"
echo "  waiting for a pod (queue + image pull + model load; up to ${ENGINE_TIMEOUT}s)"

ENGINE_POD=""
deadline=$(( $(date +%s) + ENGINE_TIMEOUT ))
while [ "$(date +%s)" -lt "$deadline" ]; do
    read -r phase pod <<< "$(kubectl -n "$NAMESPACE" get pods -l "job-name=$ENGINE_JOB" \
        -o jsonpath='{.items[0].status.phase} {.items[0].metadata.name}' 2>/dev/null)"
    [ "$phase" = "Running" ] && [ -n "$pod" ] && { ENGINE_POD="$pod"; break; }
    if [ "$phase" = "Failed" ]; then
        echo "ERROR: engine pod failed" >&2
        kubectl -n "$NAMESPACE" logs -l "job-name=$ENGINE_JOB" --tail=50 >&2
        exit 1
    fi
    sleep 10
done
[ -n "$ENGINE_POD" ] || { echo "ERROR: engine pod not Running within ${ENGINE_TIMEOUT}s" >&2; exit 1; }
echo "  pod: $ENGINE_POD"

# OS-assigned local port: a fixed one collides with a stale forward from a
# previous crashed run, which would silently target the wrong engine.
if [ "$LOCAL_PORT" = "0" ]; then
    LOCAL_PORT=$(python3 -c 'import socket;s=socket.socket();s.bind(("127.0.0.1",0));print(s.getsockname()[1]);s.close()')
fi
LLM_URL="http://127.0.0.1:$LOCAL_PORT/v1"

# start_new_session detaches the tunnel from this shell's process group, so a
# terminal hiccup cannot kill it mid-run.
setsid kubectl -n "$NAMESPACE" port-forward "pod/$ENGINE_POD" "$LOCAL_PORT:8000" \
    > "$RUN_DIR/engine-portforward.log" 2>&1 &
PF_PID=$!
echo "  tunnel: $LLM_URL (pid $PF_PID)"

echo "  waiting for the model to load and serve /v1/models"
ready=0
deadline=$(( $(date +%s) + ENGINE_TIMEOUT ))
while [ "$(date +%s)" -lt "$deadline" ]; do
    # Restart a tunnel that died while the engine was still loading.
    if ! kill -0 "$PF_PID" 2>/dev/null; then
        setsid kubectl -n "$NAMESPACE" port-forward "pod/$ENGINE_POD" "$LOCAL_PORT:8000" \
            >> "$RUN_DIR/engine-portforward.log" 2>&1 &
        PF_PID=$!
    fi
    curl -sf -m 5 "$LLM_URL/models" > /dev/null 2>&1 && { ready=1; break; }
    sleep 10
done
[ $ready -eq 1 ] || { echo "ERROR: engine never served /v1/models" >&2; exit 1; }
echo "  engine ready"

# Babysit the tunnel for the whole run: kubectl port-forward drops occasionally,
# which would otherwise fail every in-flight task.
(
    while kill -0 $$ 2>/dev/null; do
        if ! kill -0 "$PF_PID" 2>/dev/null; then
            setsid kubectl -n "$NAMESPACE" port-forward "pod/$ENGINE_POD" "$LOCAL_PORT:8000" \
                >> "$RUN_DIR/engine-portforward.log" 2>&1 &
            PF_PID=$!
        fi
        sleep 5
    done
) &

echo
echo "[3] Running the benchmark"
export PYTHONPATH="@teasbench_root@${PYTHONPATH:+:$PYTHONPATH}"
export TEASBENCH_K8S_NAMESPACE="$NAMESPACE"
# Referenced by the generated client command (see the eidf swe-bench rule in
# pipeline/configs/config.yaml). RUN_DIR and SWEAGENT_DIR are set above.
export LLM_URL RUN_DIR SWEAGENT_DIR
export AGENTCAP_DIR="${AGENTCAP_DIR:-$(cd "@teasbench_root@/../AgentCAP-teasbench" 2>/dev/null && pwd || echo "$HOME/AgentCAP")}"
@teas_env_exports@

@agentic_client_command@ 2>&1 | tee "$RUN_DIR/client.log"
RC=${PIPESTATUS[0]}
echo "  agent_cap exit: $RC"

echo
echo "[4] Results"
RESULTS_SUBDIR="@output_repo_dir@/$TIMESTAMP"
if [ $PUSH -eq 1 ]; then
    REPO_CLONE="$RUN_DIR/@results_repo@"
    if [ -n "${GIT_TOKEN:-}" ]; then
        REPO_URL="https://oauth2:${GIT_TOKEN%$'\n'}@github.com/TEAS-project/@results_repo@.git"
    else
        REPO_URL="https://github.com/TEAS-project/@results_repo@.git"
    fi
    if git clone --quiet "$REPO_URL" "$REPO_CLONE" 2>/dev/null; then
        DEST="$REPO_CLONE/$RESULTS_SUBDIR"
        mkdir -p "$DEST"
        shopt -s nullglob
        cp "$RUN_DIR"/metrics_*.json "$RUN_DIR"/metadata_*.json \
           "$RUN_DIR"/detailed-results_*.jsonl "$RUN_DIR"/output-data*.jsonl \
           "$RUN_DIR"/results.jsonl "$RUN_DIR"/*.log "$DEST/" 2>/dev/null
        cp "$ENGINE_MANIFEST" "$DEST/" 2>/dev/null
        cp "${BASH_SOURCE[0]}" "$DEST/run.sh" 2>/dev/null
        shopt -u nullglob
        ( cd "$REPO_CLONE" \
          && git config user.email "autopush@eidf" \
          && git config user.name "Pipeline Autopush" \
          && git add -A "$RESULTS_SUBDIR" \
          && git commit -q -m "auto: $RUN_NAME" \
          && git push -q "$REPO_URL" ) \
          && echo "  pushed to $RESULTS_SUBDIR" \
          || echo "  WARNING: push failed; results are still in $RUN_DIR"
    else
        echo "  WARNING: could not clone the results repo (set GIT_TOKEN); results in $RUN_DIR"
    fi
else
    echo "  --no-push: results left in $RUN_DIR"
    echo "  would have gone to $RESULTS_SUBDIR"
fi

echo
echo "=============================================================="
[ $RC -eq 0 ] && echo "RUN COMPLETE -- $RUN_DIR" || echo "RUN FAILED (rc=$RC) -- see $RUN_DIR/client.log"
echo "=============================================================="
exit $RC
